        local function ScheduleRefresh()
            if S.RefreshScheduled then
                return
            end

            S.RefreshScheduled = true

            task.delay(REFRESH_DEBOUNCE, function()
                S.RefreshScheduled = false

                if not Context.Lifetime.Alive then
