	["Features/WalkController.lua"] = [======[
-- WalkController walks Auto Mining and Auto Smithing to a spot.
--
-- Pathfinding comes first whenever the straight line is not clean: an
-- obstacle in the body's way taller than a hop (MAX_HOP_RISE), a hole too
-- wide to jump, a climb higher than a jump, a deadzone, or (with
-- KeepInsideMine) leaving the mine zone. An open line is walked straight;
-- a jumpable hole is jumped at its edge and a low bump is hopped. Paths are solved off the heartbeat, so a slow solve never stalls a
-- frame, and a path that enters a deadzone (or leaves the mine zone) is
-- refused.
--
-- When the solver finds no path, the walk detours: it steps toward the
-- open side of the obstacle nearest the heading, then tries the straight
-- line and the path again from there. Only after MAX_DETOURS in a row
-- bring it no closer does it report "failed"; an obstacle low enough to
-- hop is then still jumped as a last resort.
return {
    Name = "WalkController",
    Dependencies = {"Runtime", "CombatUtils"},

    Start = function(Context)
        local Runtime = Context.Runtime
        local Services = Context.Services
        local Players = Services.Players
        local PathfindingService = Services.PathfindingService
        local FeatureState = Context.Feature
        local AICCombatUtils = Context.AICCombatUtils

        --// How often the straight line is re-tested; holes need this often
        --// enough to jump at the edge rather than past it.
        local DIRECT_CHECK_INTERVAL = 0.1
        --// Taller than this above the feet needs a path, not a straight walk.
        local MAX_DIRECT_RISE = 6
        --// How far ahead the body probe looks for obstacles.
        local OBSTACLE_PROBE_DISTANCE = 8
        --// The body probe: as wide as the character, from BODY_PROBE_LIFT
        --// above the feet (over steps a walk takes in stride) to head height.
        local BODY_PROBE_SIZE = Vector3.new(2.4, 3.5, 2.4)
        local BODY_PROBE_LIFT = 1
        --// A surface facing up more than this is ground to walk up, not a wall.
        local WALKABLE_NORMAL_Y = 0.6
        --// Jump once the hole edge is this close.
        local HOLE_JUMP_EDGE = 2.5
        --// An obstacle with nothing above this height over it (measured from
        --// the feet) is a bump: walked straight at and hopped, not pathed
        --// round. HOP_LANDING is the clear room needed past its edge.
        local MAX_HOP_RISE = 3
        local HOP_LANDING = 2
        --// Hop once the bump is this close.
        local HOP_EDGE = 2
        --// Once on a path, stay on it at least this long so a borderline
        --// straight line does not flip the mode every frame.
        local PATH_HOLD_SECONDS = 4
        local PATH_RECALCULATE_INTERVAL = 3
        local PATH_RETRY_INTERVAL = 2
        local PATH_WAYPOINT_REACH = 3
        local PATH_DESTINATION_TOLERANCE = 4
        --// Jumping has not freed the character for this long: take a path,
        --// or solve the one being walked again.
        local STUCK_PATH_SECONDS = 1.5
        local ZONE_SAMPLE_DISTANCE = 4
        --// Detours, tried nearest the heading first, on alternating sides.
        local DETOUR_ANGLES = { 30, 60, 90, 120, 150 }
        local DETOUR_PROBE_DISTANCE = 10
        --// A side needs at least this much open ground to be worth a detour.
        local DETOUR_MIN_FREE = 4
        local DETOUR_REACH = 2
        local DETOUR_TIMEOUT = 2.5
        local MAX_DETOURS = 4
        --// Closer to the destination by this much counts as progress.
        local DETOUR_PROGRESS = 2

        local Movement = {
            Name = "WalkController",
            S = {
                Holding = false,
                PathUntil = 0,
                StuckSince = nil,
                LastDirectCheck = 0,
                DirectBlocked = false,
                --// The straight line is unsafe (hole, climb, deadzone, zone),
                --// not merely obstructed.
                Unsafe = false,
                HoleCanJump = false,
                HoleEdge = nil,
                --// Distance to an obstacle on the straight line low enough
                --// to hop, or nil.
                BumpDistance = nil,
                PathToken = 0,
                Path = {},
                Detour = nil,
                DetourSide = 1,
                DetourCount = 0,
                BestDistance = math.huge,
                ProgressDestination = nil,
            },
        }

        local S = Movement.S

        local function CanUseGround(Position, KeepInsideMine)
            if not FeatureState.IgnoreFarmZone.Enabled and AICCombatUtils.IsInsideFarmDeadzone(Position) then
                return false
            end

            return not KeepInsideMine or AICCombatUtils.IsInsideMineZone(Position)
        end

        local function SegmentStaysInMine(From, To)
            local Offset = To - From
            local Distance = Offset.Magnitude

            if Distance <= 0 then
                return AICCombatUtils.IsInsideMineZone(To)
            end

            for Travelled = ZONE_SAMPLE_DISTANCE, Distance, ZONE_SAMPLE_DISTANCE do
                if not AICCombatUtils.IsInsideMineZone(From + Offset.Unit * Travelled) then
                    return false
                end
            end

            return AICCombatUtils.IsInsideMineZone(To)
        end

        local function BuildWallParams(Character, IgnoreModel)
            local Filter = { Character }

            if IgnoreModel then
                table.insert(Filter, IgnoreModel)
            end

            local MobFolder = workspace:FindFirstChild("Mobs")
            if MobFolder then
                table.insert(Filter, MobFolder)
            end

            for _, OtherPlayer in ipairs(Players:GetPlayers()) do
                if OtherPlayer.Character and OtherPlayer.Character ~= Character then
                    table.insert(Filter, OtherPlayer.Character)
                end
            end

            if AICCombatUtils.S.DebugFolder then
                table.insert(Filter, AICCombatUtils.S.DebugFolder)
            end

            local Params = RaycastParams.new()
            Params.FilterType = Enum.RaycastFilterType.Exclude
            Params.FilterDescendantsInstances = Filter
            return Params
        end

        local function GetFeet(RootPart, Humanoid)
            --// R6 legs are not counted in HipHeight.
            local Hip = Humanoid.RigType == Enum.HumanoidRigType.R6 and 2 or Humanoid.HipHeight
            return RootPart.Position - Vector3.new(0, Hip + RootPart.Size.Y * 0.5, 0)
        end

        --// How far the body gets along Direction (flat, unit) before it hits
        --// something that is not walkable ground, or nil when nothing.
        local function CastBody(RootPart, Humanoid, Params, Direction, Distance)
            local Center = GetFeet(RootPart, Humanoid) + Vector3.new(0, BODY_PROBE_LIFT + BODY_PROBE_SIZE.Y * 0.5, 0)
            local Hit = workspace:Blockcast(CFrame.new(Center), BODY_PROBE_SIZE, Direction * Distance, Params)

            if Hit and Hit.Normal.Y < WALKABLE_NORMAL_Y then
                return Hit.Distance
            end

            return nil
        end

        --// A body probe lifted MAX_HOP_RISE: nothing there over the obstacle
        --// and HOP_LANDING past it means a jump clears it.
        local function IsHoppable(RootPart, Humanoid, Params, Direction, HitDistance)
            local Center = GetFeet(RootPart, Humanoid) + Vector3.new(0, MAX_HOP_RISE + BODY_PROBE_SIZE.Y * 0.5, 0)
            return workspace:Blockcast(CFrame.new(Center), BODY_PROBE_SIZE, Direction * (HitDistance + HOP_LANDING), Params) == nil
        end

        --// Blocked, and the distance to an obstacle low enough to hop (nil
        --// when there is none, or the one ahead is too tall to hop).
        local function CheckObstacleAhead(RootPart, Humanoid, Character, Destination, IgnoreModel)
            local Offset = Destination - RootPart.Position
            local Flat = Vector3.new(Offset.X, 0, Offset.Z)

            if Flat.Magnitude <= 0.5 then
                return false, nil
            end

            local Params = BuildWallParams(Character, IgnoreModel)
            local Distance = math.min(Flat.Magnitude, OBSTACLE_PROBE_DISTANCE)
            local HitDistance = CastBody(RootPart, Humanoid, Params, Flat.Unit, Distance)

            if not HitDistance then
                return false, nil
            end

            if IsHoppable(RootPart, Humanoid, Params, Flat.Unit, HitDistance) then
                return false, HitDistance
            end

            return true, nil
        end

        --// Re-tests the straight line at most every DIRECT_CHECK_INTERVAL.
        local function UpdateDirectCheck(now, RootPart, Humanoid, Character, Destination, Options)
            if now - S.LastDirectCheck < DIRECT_CHECK_INTERVAL then
                return
            end

            S.LastDirectCheck = now

            local IsHole, CanJump, Edge = AICCombatUtils.IsHoleAhead(Destination)
            S.HoleCanJump = IsHole and CanJump
            S.HoleEdge = Edge

            S.Unsafe = (IsHole and not CanJump)
                or Destination.Y - RootPart.Position.Y > MAX_DIRECT_RISE
                or AICCombatUtils.IsPathThroughDeadzone(Destination)
                or (Options.KeepInsideMine and not SegmentStaysInMine(RootPart.Position, Destination))

            local Blocked, BumpDistance = CheckObstacleAhead(RootPart, Humanoid, Character, Destination, Options.Ignore)
            S.BumpDistance = BumpDistance
            S.DirectBlocked = S.Unsafe or Blocked
        end

        local function JumpHoleIfClose()
            if S.HoleCanJump and S.HoleEdge and S.HoleEdge <= HOLE_JUMP_EDGE then
                AICCombatUtils.DoJump()
            end
        end

        local function JumpBumpIfClose()
            if S.BumpDistance and S.BumpDistance <= HOP_EDGE then
                AICCombatUtils.DoJump()
            end
        end

        local function IsRouteAllowed(Waypoints, KeepInsideMine)
            for Index = 2, #Waypoints do
                if not CanUseGround(Waypoints[Index].Position, KeepInsideMine) then
                    return false
                end
            end

            return true
        end

        local function RequestPath(RootPart, Destination, KeepInsideMine)
            local Path = S.Path
            local From = RootPart.Position
            local AgentRadius = math.max(RootPart.Size.X * 0.5, 2)
            local AgentHeight = math.max(RootPart.Size.Y, 5)

            S.PathToken += 1
            local Token = S.PathToken
            Path.Computing = true

            task.spawn(function()
                local Solver = PathfindingService:CreatePath({
                    AgentRadius = AgentRadius,
                    AgentHeight = AgentHeight,
                    AgentCanJump = true,
                    WaypointSpacing = 4,
                })

                local Ok = pcall(function()
                    Solver:ComputeAsync(From, Destination)
                end)

                --// Reset or superseded while solving.
                if Token ~= S.PathToken then
                    return
                end

                Path.Computing = false

                local Waypoints = Ok and Solver.Status == Enum.PathStatus.Success and Solver:GetWaypoints()

                if not Waypoints or #Waypoints < 2 or not IsRouteAllowed(Waypoints, KeepInsideMine) then
                    Path.Waypoints = nil
                    Path.FailedAt = os.clock()
                    return
                end

                Path.Waypoints = Waypoints
                Path.Index = 2
                Path.Destination = Destination
                Path.Time = os.clock()
                Path.FailedAt = nil
            end)
        end

        --// "moving", "waiting" while a path is being solved, "failed" when
        --// no allowed path exists, or "done" once the path is walked.
        local function FollowPath(now, RootPart, Humanoid, Destination, KeepInsideMine)
            local Path = S.Path
            local Stale = not Path.Waypoints
                or (Path.Destination - Destination).Magnitude > PATH_DESTINATION_TOLERANCE
                or now - Path.Time >= PATH_RECALCULATE_INTERVAL
            local MayRetry = not Path.FailedAt or now - Path.FailedAt >= PATH_RETRY_INTERVAL

            if Stale and not Path.Computing and MayRetry then
                RequestPath(RootPart, Destination, KeepInsideMine)
            end

            if not Path.Waypoints then
                return Path.Computing and "waiting" or "failed"
            end

            while Path.Index <= #Path.Waypoints do
                local Waypoint = Path.Waypoints[Path.Index]

                if AICCombatUtils.GetHorizontalDistance(Waypoint.Position, RootPart.Position) <= PATH_WAYPOINT_REACH then
                    Path.Index += 1
                    continue
                end

                --// The solver marks jumps generously; only take one when
                --// something is in the way or the character has stalled.
                if Waypoint.Action == Enum.PathWaypointAction.Jump
                    and (AICCombatUtils.IsJumpableObstacleAhead(Waypoint.Position) or AICCombatUtils.IsStuck())
                then
                    AICCombatUtils.DoJump()
                end

                JumpHoleIfClose()
                Humanoid:MoveTo(Waypoint.Position)
                return "moving"
            end

            Path.Waypoints = nil
            S.PathUntil = 0
            return "done"
        end

        local function UpdateStuck(now)
            if not AICCombatUtils.IsStuck() then
                S.StuckSince = nil
                return
            end

            S.StuckSince = S.StuckSince or now
            AICCombatUtils.DoJump()

            if now - S.StuckSince >= STUCK_PATH_SECONDS then
                --// Already on a path and still stuck: solve it again from here.
                if now < S.PathUntil then
                    S.Path.Time = 0
                end

                S.PathUntil = now + PATH_HOLD_SECONDS
                S.StuckSince = nil
                AICCombatUtils.ResetStuckTracker()
            end
        end

        ------------------------------------------------------------------------
        --// Detours, for when the solver finds no path
        ------------------------------------------------------------------------

        --// Detours are only worth repeating while they lead somewhere.
        local function TrackProgress(RootPart, Destination)
            if not S.ProgressDestination
                or (S.ProgressDestination - Destination).Magnitude > PATH_DESTINATION_TOLERANCE
            then
                S.ProgressDestination = Destination
                S.BestDistance = math.huge
                S.DetourCount = 0
            end

            local Distance = (Destination - RootPart.Position).Magnitude

            if Distance < S.BestDistance - DETOUR_PROGRESS then
                S.BestDistance = Distance
                S.DetourCount = 0
            end
        end

        local function IsDetourAllowed(RootPart, Candidate, KeepInsideMine)
            local IsHole, CanJump = AICCombatUtils.IsHoleAhead(Candidate)

            return CanUseGround(Candidate, KeepInsideMine)
                and not (IsHole and not CanJump)
                and not AICCombatUtils.IsPathThroughDeadzone(Candidate)
                and not (KeepInsideMine and not SegmentStaysInMine(RootPart.Position, Candidate))
        end

        --// The open side nearest the heading, starting on the other side
        --// from last time so two detours do not hit the same wall.
        local function FindDetour(RootPart, Humanoid, Character, Destination, Options)
            local Offset = Destination - RootPart.Position
            local Heading = Vector3.new(Offset.X, 0, Offset.Z)
            Heading = Heading.Magnitude > 0.01 and Heading.Unit or RootPart.CFrame.LookVector

            local Params = BuildWallParams(Character, Options.Ignore)
            S.DetourSide = -S.DetourSide

            for _, Angle in ipairs(DETOUR_ANGLES) do
                for _, Sign in ipairs({ S.DetourSide, -S.DetourSide }) do
                    local Direction = CFrame.Angles(0, math.rad(Angle * Sign), 0):VectorToWorldSpace(Heading)
                    local HitDistance = CastBody(RootPart, Humanoid, Params, Direction, DETOUR_PROBE_DISTANCE)
                    local Free = HitDistance and HitDistance - 1 or DETOUR_PROBE_DISTANCE

                    if Free >= DETOUR_MIN_FREE then
                        local Candidate = RootPart.Position + Direction * Free

                        if IsDetourAllowed(RootPart, Candidate, Options.KeepInsideMine) then
                            return Candidate
                        end
                    end
                end
            end

            return nil
        end

        local function StartDetour(now, RootPart, Humanoid, Character, Destination, Options)
            if S.DetourCount >= MAX_DETOURS then
                return false
            end

            local Position = FindDetour(RootPart, Humanoid, Character, Destination, Options)

            if not Position then
                return false
            end

            S.DetourCount += 1
            S.Detour = { Position = Position, Until = now + DETOUR_TIMEOUT }
            AICCombatUtils.ResetStuckTracker()
            return true
        end

        --// True while a detour has this frame. Once reached (or timed out),
        --// the straight line and the path are tried again from there.
        local function WalkDetour(now, RootPart, Humanoid)
            local Detour = S.Detour

            if not Detour then
                return false
            end

            if now > Detour.Until or AICCombatUtils.GetHorizontalDistance(RootPart.Position, Detour.Position) <= DETOUR_REACH then
                S.Detour = nil
                S.PathUntil = 0
                S.LastDirectCheck = 0
                return false
            end

            AICCombatUtils.DoJumpIfObstacle(Detour.Position)
            Humanoid:MoveTo(Detour.Position)
            return true
        end

        ------------------------------------------------------------------------

        --// Stands still. A MoveTo stays active until reached, so it is
        --// cancelled once by moving to where we already are.
        function Movement:Hold()
            local _, Humanoid, RootPart = Runtime:GetCharacter()

            if not Humanoid or not RootPart then
                return
            end

            if not S.Holding then
                S.Holding = true
                Humanoid:MoveTo(RootPart.Position)
            end

            Humanoid:Move(Vector3.zero)
        end

        --// Options:
        --//   Ignore          model the obstacle probes look through (the ore)
        --//   KeepInsideMine  never step outside the mine zones
        --// Returns "moving", "waiting" (standing while a path is solved) or
        --// "failed" (no allowed way there).
        function Movement:MoveTo(Destination, Options)
            local Character, Humanoid, RootPart = Runtime:GetCharacter()

            if not Humanoid or not RootPart then
                return "failed"
            end

            Options = Options or {}

            local now = os.clock()
            local FaceOrientation = Runtime:GetFaceOrientation()

            if FaceOrientation then
                FaceOrientation.Enabled = false
            end

            Humanoid.AutoRotate = true
            S.Holding = false

            UpdateStuck(now)
            TrackProgress(RootPart, Destination)

            if WalkDetour(now, RootPart, Humanoid) then
                return "moving"
            end

            UpdateDirectCheck(now, RootPart, Humanoid, Character, Destination, Options)

            if S.DirectBlocked and now >= S.PathUntil then
                S.PathUntil = now + PATH_HOLD_SECONDS
            end

            if now < S.PathUntil then
                local Result = FollowPath(now, RootPart, Humanoid, Destination, Options.KeepInsideMine)

                if Result == "moving" then
                    return Result
                end

                if Result == "waiting" then
                    self:Hold()
                    return Result
                end

                --// No path: go round the obstacle and try again from there.
                if Result == "failed" then
                    if StartDetour(now, RootPart, Humanoid, Character, Destination, Options) then
                        WalkDetour(now, RootPart, Humanoid)
                        return "moving"
                    end

                    --// Out of detours. Never walk an unsafe line (the hole or
                    --// the deadzone); an obstacle is still hopped if it is low
                    --// enough, otherwise give up.
                    if S.Unsafe or (S.DirectBlocked and not AICCombatUtils.IsJumpableObstacleAhead(Destination)) then
                        self:Hold()
                        return "failed"
                    end
                end
            end

            JumpHoleIfClose()
            JumpBumpIfClose()
            AICCombatUtils.DoJumpIfObstacle(Destination)
            Humanoid:MoveTo(Destination)
            return "moving"
        end

        --// A ground spot Standoff studs out from Part's surface, on our side.
        --// Ores and tables are solid, so neither MoveTo nor a path can end
        --// inside one. Ignore is the model Part belongs to.
        function Movement:GetApproachPoint(Part, Standoff, Ignore)
            local Character, _, RootPart = Runtime:GetCharacter()
            local Offset = RootPart and RootPart.Position - Part.Position or Vector3.xAxis
            local Flat = Vector3.new(Offset.X, 0, Offset.Z)
            local Direction = Flat.Magnitude > 0.01 and Flat.Unit or Vector3.xAxis
            local Point = Part.Position + Direction * (math.max(Part.Size.X, Part.Size.Z) * 0.5 + Standoff)

            local Params = RaycastParams.new()
            Params.FilterType = Enum.RaycastFilterType.Exclude
            Params.FilterDescendantsInstances = { Character, Ignore, AICCombatUtils.S.DebugFolder }

            local Hit = workspace:Raycast(Point + Vector3.new(0, 8, 0), Vector3.new(0, -30, 0), Params)

            return Hit and Hit.Position + Vector3.new(0, 3, 0) or Point
        end

        function Movement:Reset()
            S.PathToken += 1
            S.Holding = false
            S.PathUntil = 0
            S.StuckSince = nil
            S.LastDirectCheck = 0
            S.DirectBlocked = false
            S.BumpDistance = nil
            S.Unsafe = false
            S.HoleCanJump = false
            S.HoleEdge = nil
            S.Detour = nil
            S.DetourCount = 0
            S.BestDistance = math.huge
            S.ProgressDestination = nil
            table.clear(S.Path)
        end

        return Movement
    end,
}
]======],
	["Features/WaypointLoop.lua"] = [======[
-- WaypointLoop: farm only the farm zones paired with a waypoint, walking the
-- route between them.
--
-- Each waypoint may be paired with one farm zone, and each farm zone may have
-- its own target list (empty = the Enemy Priority list).
--   * The route is walked as usual up to the first paired waypoint, where the
--     loop takes over.
--   * It always heads for the closest paired zone (walking distance along the
--     route) worth visiting: targets visible there, or not yet found empty
--     and not dead according to workspace.RespawnTimers. The choice is made
--     again at every waypoint, so a closer zone with a target is never
--     walked past.
--   * A zone found empty is remembered and skipped until one of its targets
--     respawns (its timer is removed).
--   * With every zone dead, walk to the zone whose target respawns soonest
--     and wait there, instead of walking back and forth.
-- The walk only uses the waypoints between paired ones: it never heads back
-- past the first or last paired waypoint (e.g. first pair on #34 never walks
-- back to #33).
return {
    Name = "WaypointLoop",
    IsFeature = true,
    Dependencies = {"Runtime", "ProfileManager", "Components", "Targeting", "Waypoints", "Farmzone", "RespawnTimers"},

    Start = function(Context)
        local Runtime = Context.Runtime
        local Players = Context.Services.Players
        local CONFIG = Context.CONFIG
        local FeatureState = Context.Feature
        local AICConfig = Context.AICConfig
        local AICProfile = Context.AICProfile
        local AICCombat = Context.AICCombat
        local AICCombatUtils = Context.AICCombatUtils
        local AICFeature = Context.AICFeature
        local AICUI = Context.AICUI
        local AICDebug = Context.AICDebug
        local UIRef = Context.UIRef
        local NotifyAction = Context.NotifyAction

        --// How often zones are rescanned for targets.
        local ZONE_SCAN_INTERVAL = 0.25
        --// How long a zone must stay empty before it counts as cleared, so a
        --// scan that misses a mob for a moment does not send us away.
        local ZONE_CLEAR_GRACE = 1.5
        --// A zone whose timers say its target is alive, but which was found
        --// empty, is looked at again after this long.
        local CHECKED_EXPIRE = 60

        local Feature = {
            Name = "WaypointLoop",
            IsFeature = true,
        }

        AICFeature.S.Loop = {
            --// Waypoint the character is at, or nil before the route ends.
            Index = nil,
            --// Paired waypoint being walked to or fought at.
            Goal = nil,
            --// When the goal zone was first seen empty, or nil.
            EmptySince = nil,
            --// [ZoneIndex] = when that zone was last found empty. Kept across
            --// deaths: it describes the world, not the character.
            Checked = {},
            ScanTime = 0,
            ScanResult = {},
        }

        local Loop = AICFeature.S.Loop

        local function ZoneTargetNames(Zone)
            if type(Zone.Targets) == "table" and #Zone.Targets > 0 then
                return Zone.Targets
            end

            return CONFIG.TARGET_ENTITY_PRIORITY or {}
        end

        --// Waypoints paired with an existing farm zone, in route order.
        local function PairedWaypoints(PlaceConfig)
            local List = {}

            for WaypointIndex, ZoneIndex in ipairs(PlaceConfig.WAYPOINT_ZONES or {}) do
                if ZoneIndex > 0 and PlaceConfig.WAYPOINTS[WaypointIndex] and PlaceConfig.FARM_ZONES[ZoneIndex] then
                    table.insert(List, WaypointIndex)
                end
            end

            return List
        end

        --// True when a living target of this zone's list stands inside it.
        local function ScanZone(Zone)
            local Names = ZoneTargetNames(Zone)

            if #Names == 0 then
                return false
            end

            local MobFolder = workspace:FindFirstChild("Mobs")
            local Candidates = MobFolder and MobFolder:GetChildren() or {}

            for _, OtherPlayer in ipairs(Players:GetPlayers()) do
                if OtherPlayer.Character then
                    table.insert(Candidates, OtherPlayer.Character)
                end
            end

            for _, Mob in ipairs(Candidates) do
                local EntityName = AICCombat.GetTargetEntityName(Mob)

                if EntityName and table.find(Names, EntityName) then
                    local MobHumanoid = Mob:FindFirstChildOfClass("Humanoid")
                    local MobRoot = Mob:FindFirstChild("HumanoidRootPart")

                    if MobHumanoid
                        and MobRoot
                        and MobHumanoid.Health > 0
                        and AICCombatUtils.IsPositionInsideZone(MobRoot.Position, Zone)
                        and not AICCombatUtils.IsInsideFarmDeadzone(MobRoot.Position)
                    then
                        return true
                    end
                end
            end

            return false
        end

        local function ZoneHasTargets(PlaceConfig, ZoneIndex, now)
            if now - Loop.ScanTime >= ZONE_SCAN_INTERVAL then
                Loop.ScanTime = now
                table.clear(Loop.ScanResult)
            end

            if Loop.ScanResult[ZoneIndex] == nil then
                local Zone = PlaceConfig.FARM_ZONES[ZoneIndex]
                Loop.ScanResult[ZoneIndex] = Zone ~= nil and ScanZone(Zone)
            end

            return Loop.ScanResult[ZoneIndex]
        end

        local function HasOwnTargets(Zone)
            return type(Zone.Targets) == "table" and #Zone.Targets > 0
        end

        --// Respawn timers of a zone with its own target list:
        --//   Dead     every target is waiting to respawn
        --//   Soonest  seconds until the first of them is back, or nil
        --// Zones on the Enemy Priority list have no timer view (nil, nil).
        local function ZoneRespawn(Zone)
            if not HasOwnTargets(Zone) or not AICFeature.GetRespawnState then
                return nil, nil
            end

            local Dead, Soonest = true, nil

            for _, Name in ipairs(Zone.Targets) do
                local Pending, Remaining = AICFeature.GetRespawnState(Name)

                if Pending == 0 then
                    Dead = false
                elseif Remaining then
                    Soonest = math.min(Soonest or math.huge, Remaining)
                end
            end

            return Dead, Soonest
        end

        --// A zone we stood in and found empty is not revisited until one of
        --// its targets respawns. Where the timers claim a target is alive
        --// but it was not there (it may have wandered off), look again after
        --// CHECKED_EXPIRE; a zone with no timer view waits for a respawn.
        local function IsCheckedEmpty(PlaceConfig, ZoneIndex, now)
            local CheckedAt = Loop.Checked[ZoneIndex]

            if not CheckedAt then
                return false
            end

            local Zone = PlaceConfig.FARM_ZONES[ZoneIndex]

            if Zone and HasOwnTargets(Zone) and now - CheckedAt >= CHECKED_EXPIRE then
                Loop.Checked[ZoneIndex] = nil
                return false
            end

            return true
        end

        --// Worth walking to: targets are visible there, or nothing says the
        --// zone is empty (not checked empty, timers do not say all dead).
        local function IsZoneCandidate(PlaceConfig, ZoneIndex, now)
            if ZoneHasTargets(PlaceConfig, ZoneIndex, now) then
                return true
            end

            if IsCheckedEmpty(PlaceConfig, ZoneIndex, now) then
                return false
            end

            local Zone = PlaceConfig.FARM_ZONES[ZoneIndex]
            return Zone ~= nil and ZoneRespawn(Zone) ~= true
        end

        --// Walking distance in studs along the route between two waypoints.
        local function RouteDistance(PlaceConfig, From, To)
            local Waypoints = PlaceConfig.WAYPOINTS
            local Step = To > From and 1 or -1
            local Total = 0

            for Index = From, To - Step, Step do
                Total += (Waypoints[Index + Step] - Waypoints[Index]).Magnitude
            end

            return Total
        end

        --// Where to go from the current waypoint:
        --//   1. the closest paired zone (walking distance) worth visiting;
        --//   2. with none, the zone whose target respawns soonest, to wait
        --//      there;
        --//   3. nil when nothing is known: stay where we are.
        local function SelectGoal(PlaceConfig, Paired, now)
            local Best, BestDistance = nil, math.huge

            for _, WaypointIndex in ipairs(Paired) do
                local Distance = RouteDistance(PlaceConfig, Loop.Index, WaypointIndex)

                if Distance < BestDistance
                    and IsZoneCandidate(PlaceConfig, PlaceConfig.WAYPOINT_ZONES[WaypointIndex], now)
                then
                    Best, BestDistance = WaypointIndex, Distance
                end
            end

            if Best then
                return Best
            end

            local BestRespawn = math.huge

            for _, WaypointIndex in ipairs(Paired) do
                local Zone = PlaceConfig.FARM_ZONES[PlaceConfig.WAYPOINT_ZONES[WaypointIndex]]
                local _, Soonest = ZoneRespawn(Zone)

                if Soonest then
                    local Distance = RouteDistance(PlaceConfig, Loop.Index, WaypointIndex)

                    if Soonest < BestRespawn or (Soonest == BestRespawn and Distance < BestDistance) then
                        Best, BestRespawn, BestDistance = WaypointIndex, Soonest, Distance
                    end
                end
            end

            return Best
        end

        --// Nearest paired waypoint regardless of targets.
        local function NearestGoal(PlaceConfig, Paired)
            local Best, BestDistance = nil, math.huge

            for _, WaypointIndex in ipairs(Paired) do
                local Distance = RouteDistance(PlaceConfig, Loop.Index, WaypointIndex)

                if Distance < BestDistance then
                    Best, BestDistance = WaypointIndex, Distance
                end
            end

            return Best
        end

        --// A respawn makes every zone hunting that enemy worth a visit again.
        function AICFeature.OnEnemyRespawned(EnemyName)
            local PlaceConfig = Runtime:GetPlaceConfig()
            local Wanted = string.lower(EnemyName)

            for ZoneIndex, Zone in ipairs(PlaceConfig and PlaceConfig.FARM_ZONES or {}) do
                for _, Name in ipairs(ZoneTargetNames(Zone)) do
                    if string.lower(Name) == Wanted then
                        Loop.Checked[ZoneIndex] = nil
                        break
                    end
                end
            end
        end

        --// Waypoint closest to the character, for picking the loop up when
        --// it did not start from the route (e.g. switched on mid-farm).
        local function NearestWaypointIndex(PlaceConfig, RootPart)
            local Best, BestDistance = #PlaceConfig.WAYPOINTS, math.huge

            for Index, Position in ipairs(PlaceConfig.WAYPOINTS) do
                local Distance = (Position - RootPart.Position).Magnitude

                if Distance < BestDistance then
                    Best, BestDistance = Index, Distance
                end
            end

            return Best
        end

        local function StandStill(Humanoid)
            local FaceOrientation = Runtime:GetFaceOrientation()

            if FaceOrientation then
                FaceOrientation.Enabled = false
            end

            Humanoid.AutoRotate = true
            Humanoid:Move(Vector3.zero)
        end

        --// Walks to the neighbouring waypoint NextIndex; on arrival that becomes
        --// the current waypoint, and its wait time (if any) is honoured.
        local function StepTo(PlaceConfig, NextIndex, Humanoid, RootPart, now)
            local Target = PlaceConfig.WAYPOINTS[NextIndex]
            local Offset = Target - RootPart.Position
            local Horizontal = Vector3.new(Offset.X, 0, Offset.Z).Magnitude
            local Reach = tonumber(PlaceConfig.REACH_DISTANCE) or 5

            local VerticalOk = math.abs(Offset.Y) <= math.max(Reach, CONFIG.JUMP_HEIGHT + 2)
            local IsJumpWaypoint, JumpReached = AICConfig.CheckJumpWaypoint(PlaceConfig, NextIndex, Horizontal)

            --// A Jump waypoint: jump at it and head straight on to the
            --// next one, without stopping (see AutoFarming's route).
            if IsJumpWaypoint then
                if JumpReached and VerticalOk and Humanoid.FloorMaterial ~= Enum.Material.Air then
                    Loop.Index = NextIndex
                    AICCombatUtils.DoJump()
                    --// Keep the run-up going; walking back to this waypoint
                    --// would kill the jump. The next frame heads on.
                    Humanoid:Move(AICCombatUtils.GetFlatLook(RootPart))
                    return false
                end
            elseif Horizontal <= Reach and VerticalOk then
                Loop.Index = NextIndex

                local Wait = tonumber(PlaceConfig.WAYPOINT_WAITS and PlaceConfig.WAYPOINT_WAITS[NextIndex]) or 0

                if Wait > 0 then
                    AICFeature.S.WaypointWaitUntil = now + Wait
                end

                StandStill(Humanoid)
                return true
            end

            local FaceOrientation = Runtime:GetFaceOrientation()

            if FaceOrientation then
                FaceOrientation.Enabled = false
            end

            Humanoid.AutoRotate = true
            Humanoid:MoveTo(Target)

            if not AICCombatUtils.DoJumpIfRouteHole() then
                AICCombatUtils.DoJumpIfObstacle(Target)
            end

            return false
        end

        function AICFeature.ResetWaypointLoop()
            Loop.Index = nil
            Loop.Goal = nil
            Loop.EmptySince = nil
            table.clear(Loop.ScanResult)
            AICCombatUtils.S.ActiveZoneIndex = nil
        end

        --// Paired waypoints when the loop applies, else nil.
        local function GetActivePaired()
            local PlaceConfig = Runtime:GetPlaceConfig()

            if not FeatureState.WaypointLoop.Enabled
                or FeatureState.AutoFind.Enabled
                or FeatureState.IgnoreFarmZone.Enabled
                or not PlaceConfig
                or #PlaceConfig.WAYPOINTS == 0
            then
                return nil
            end

            local Paired = PairedWaypoints(PlaceConfig)
            return #Paired > 0 and Paired or nil
        end

        --// First paired waypoint: the route hands over to the loop there.
        --// nil when the loop does not apply and the route runs to the end.
        function AICFeature.GetWaypointLoopEntry()
            local Paired = GetActivePaired()
            return Paired and Paired[1] or nil
        end

        --// Called by the route on reaching the entry waypoint (or beyond).
        function AICFeature.EnterWaypointLoop(WaypointIndex)
            AICFeature.ResetWaypointLoop()
            Loop.Index = WaypointIndex
        end

        --// Called by the farm loop once the route has been walked.
        --//   nil     the loop does not apply; farm as before
        --//   "fight" fight (or wait) inside the active paired zone
        --//   "move"  the loop moved the character this frame
        function AICFeature.WaypointLoopStep(now)
            local PlaceConfig = Runtime:GetPlaceConfig()
            local _, Humanoid, RootPart = Runtime:GetCharacter()
            local Paired = GetActivePaired()

            if not Paired or not Humanoid or not RootPart then
                if Loop.Index then
                    AICFeature.ResetWaypointLoop()
                end

                return nil
            end

            --// Not entered from the route: pick up from the nearest waypoint.
            if not Loop.Index or not PlaceConfig.WAYPOINTS[Loop.Index] then
                Loop.Index = NearestWaypointIndex(PlaceConfig, RootPart)
                Loop.Goal = nil
            end

            --// No goal yet, or its pair was removed.
            if not Loop.Goal or not table.find(Paired, Loop.Goal) then
                Loop.Goal = SelectGoal(PlaceConfig, Paired, now) or NearestGoal(PlaceConfig, Paired)
                Loop.EmptySince = nil
            end

            if Loop.Goal ~= Loop.Index then
                AICCombatUtils.S.ActiveZoneIndex = nil
                AICCombat.S.ClosestTarget = nil

                local Arrived = StepTo(PlaceConfig, Loop.Index + (Loop.Goal > Loop.Index and 1 or -1), Humanoid, RootPart, now)

                --// Plan again at every waypoint: a closer zone with a target
                --// (the one we are standing at, say) wins over the old goal.
                if Arrived then
                    local Next = SelectGoal(PlaceConfig, Paired, now)

                    if Next and Next ~= Loop.Goal then
                        Loop.Goal = Next
                        Loop.EmptySince = nil
                    end
                end

                return "move"
            end

            local ZoneIndex = PlaceConfig.WAYPOINT_ZONES[Loop.Goal]
            AICCombatUtils.S.ActiveZoneIndex = ZoneIndex

            if ZoneHasTargets(PlaceConfig, ZoneIndex, now) then
                Loop.EmptySince = nil
                Loop.Checked[ZoneIndex] = nil
                return "fight"
            end

            Loop.EmptySince = Loop.EmptySince or now

            --// Zone cleared: remember it, then go to the closest zone still
            --// worth visiting, or wait at the one that respawns first. With
            --// nothing known the goal stays and we wait here.
            if now - Loop.EmptySince >= ZONE_CLEAR_GRACE then
                Loop.Checked[ZoneIndex] = Loop.Checked[ZoneIndex] or now

                local Next = SelectGoal(PlaceConfig, Paired, now)

                if Next and Next ~= Loop.Goal then
                    Loop.Goal = Next
                    Loop.EmptySince = nil
                end
            end

            return "fight"
        end

        function Feature:Update()
        end

        ------------------------------------------------------------------------
        --// UI: waypoint pairing (Waypoints section) and zone targets (Farmzone)
        ------------------------------------------------------------------------
        local SelectedPairWaypoint = 1
        --// Options the pair pickers were built with (joined), so an
        --// unchanged list keeps its dropdown.
        local PairPickerSignatures = { Waypoint = nil, Zone = nil }

        local function ZoneOptionLabel(ZoneIndex)
            return ZoneIndex > 0 and ("Farm Zone #" .. ZoneIndex) or "None"
        end

        function AICUI.RefreshWaypointPairPickers()
            local Section = UIRef.WaypointSection

            if not Section then
                return
            end

            local PlaceConfig = Runtime:GetPlaceConfig()
            local WaypointOptions = {}
            local ZoneOptions = { "None" }

            for Index in ipairs(PlaceConfig.WAYPOINTS) do
                table.insert(WaypointOptions, "Waypoint #" .. Index)
            end

            for Index in ipairs(PlaceConfig.FARM_ZONES) do
                table.insert(ZoneOptions, ZoneOptionLabel(Index))
            end

            if #WaypointOptions == 0 then
                WaypointOptions = { "No Waypoints" }
            end

            SelectedPairWaypoint = math.clamp(SelectedPairWaypoint, 1, math.max(1, #PlaceConfig.WAYPOINTS))

            --// The same options keep the dropdowns: they are rebuilt only when
            --// the lists change, never from inside their own pick handler
            --// for nothing (which could swallow the next click).
            local WaypointSignature = table.concat(WaypointOptions, "\n")
            local ZoneSignature = table.concat(ZoneOptions, "\n")

            if not UIRef.PairWaypointPicker or PairPickerSignatures.Waypoint ~= WaypointSignature then
                PairPickerSignatures.Waypoint = WaypointSignature

                UIRef.PairWaypointPicker = AICUI.ReplaceDropdown(UIRef.PairWaypointPicker, Section, "Pair Waypoint", WaypointOptions, function(Value)
                    local Current = Runtime:GetPlaceConfig()
                    local Index = table.find(WaypointOptions, Value)

                    if Index and Current.WAYPOINTS[Index] then
                        SelectedPairWaypoint = Index

                        if UIRef.PairZonePicker then
                            UIRef.PairZonePicker:Set(ZoneOptionLabel(Current.WAYPOINT_ZONES[Index] or 0), false)
                        end
                    end
                end)
            end

            if UIRef.PairZonePicker and PairPickerSignatures.Zone == ZoneSignature then
                if PlaceConfig.WAYPOINTS[SelectedPairWaypoint] then
                    UIRef.PairWaypointPicker:Set(WaypointOptions[SelectedPairWaypoint], false)
                    UIRef.PairZonePicker:Set(ZoneOptionLabel(PlaceConfig.WAYPOINT_ZONES[SelectedPairWaypoint] or 0), false)
                end

                return
            end

            PairPickerSignatures.Zone = ZoneSignature

            UIRef.PairZonePicker = AICUI.ReplaceDropdown(UIRef.PairZonePicker, Section, "Paired Farm Zone", ZoneOptions, function(Value)
                local Current = Runtime:GetPlaceConfig()

                if not Current.WAYPOINTS[SelectedPairWaypoint] then
                    return
                end

                if not AICProfile.S.ActiveProfileName then
                    AICUI.SetProfileStatus("CREATE / LOAD PROFILE FIRST")
                    return
                end

                local ZoneIndex = (table.find(ZoneOptions, Value) or 1) - 1

                Current.WAYPOINT_ZONES = AICConfig.NormalizeZonePairs(Current.WAYPOINT_ZONES, #Current.WAYPOINTS, #Current.FARM_ZONES)

                --// Nothing changed: do not save or rebuild. Rebuilding recreates
                --// this dropdown, which is how the startup freeze looped.
                if Current.WAYPOINT_ZONES[SelectedPairWaypoint] == ZoneIndex then
                    return
                end

                Current.WAYPOINT_ZONES[SelectedPairWaypoint] = ZoneIndex
                AICFeature.ResetWaypointLoop()
                AICProfile.SaveActiveProfile()
                AICUI.RefreshWaypointList()
                AICUI.SetProfileStatus("WAYPOINT #" .. SelectedPairWaypoint .. " -> " .. ZoneOptionLabel(ZoneIndex):upper())
            end)

            if PlaceConfig.WAYPOINTS[SelectedPairWaypoint] then
                UIRef.PairWaypointPicker:Set(WaypointOptions[SelectedPairWaypoint], false)
                UIRef.PairZonePicker:Set(ZoneOptionLabel(PlaceConfig.WAYPOINT_ZONES[SelectedPairWaypoint] or 0), false)
            end
        end

        --// Targets of the farm zone picked in "Edit Farm Zone".
        local function SelectedZone()
            local PlaceConfig = Runtime:GetPlaceConfig()
            return PlaceConfig.FARM_ZONES[AICProfile.S.SelectedFarmZoneIndex]
        end

        function AICUI.RefreshZoneTargets()
            local Section = UIRef.FarmzoneSection

            if not Section or not UIRef.ZoneTargetsComponent then
                return
            end

            local Zone = SelectedZone()
            UIRef.ZoneTargetsComponent:SetPriority(table.clone(Zone and Zone.Targets or {}))

            --// Choices: everything detected nearby plus the Enemy Priority list.
            local Options = {}

            for _, Name in ipairs(AICCombat.GetDetectedEnemyEntities()) do
                table.insert(Options, Name)
            end

            for _, Name in ipairs(CONFIG.TARGET_ENTITY_PRIORITY or {}) do
                if not table.find(Options, Name) then
                    table.insert(Options, Name)
                end
            end

            for Index = #Options, 1, -1 do
                if Zone and table.find(Zone.Targets or {}, Options[Index]) then
                    table.remove(Options, Index)
                end
            end

            if #Options == 0 then
                Options = { "No detected enemies" }
            end

            UIRef.ZoneTargetDropdown = AICUI.ReplaceDropdown(UIRef.ZoneTargetDropdown, Section, "Add Zone Target", Options, function(Value)
                local Current = SelectedZone()

                if not Current or Value == "No detected enemies" then
                    return
                end

                if not AICProfile.S.ActiveProfileName then
                    AICUI.SetProfileStatus("CREATE / LOAD PROFILE FIRST")
                    return
                end

                Current.Targets = Current.Targets or {}

                if not table.find(Current.Targets, Value) then
                    table.insert(Current.Targets, Value)
                    AICProfile.SaveActiveProfile()
                    NotifyAction("Zone Targets", "Added " .. Value)
                end

                AICUI.RefreshZoneTargets()
            end)
        end

        if UIRef.WaypointSection then
            FeatureState.WaypointLoop.Button = UIRef.WaypointSection:AddToggle{
                Name = "Waypoint Loop",
                Default = FeatureState.WaypointLoop.Enabled,
                Callback = function(Value)
                    FeatureState.WaypointLoop.Enabled = Value
                    AICFeature.ResetWaypointLoop()
                    AICProfile.SaveActiveProfile()
                end,
            }

            AICUI.RefreshWaypointPairPickers()
        end

        if UIRef.FarmzoneSection then
            UIRef.ZoneTargetsComponent = UIRef.FarmzoneSection:AddPriority("Zone Targets", {})

            --// The list mirrors the selected zone's Targets; every edit is
            --// written back to the zone and saved.
            local Component = UIRef.ZoneTargetsComponent
            local OriginalRemove = Component.Remove
            local OriginalMoveUp = Component.MoveUp
            local OriginalMoveDown = Component.MoveDown

            local function Commit(Component)
                local Zone = SelectedZone()

                if Zone then
                    Zone.Targets = table.clone(Component.Priority)
                    AICProfile.SaveActiveProfile()
                end

                AICUI.RefreshZoneTargets()
            end

            local function Guard()
                if AICProfile.S.ActiveProfileName and SelectedZone() then
                    return true
                end

                AICUI.SetProfileStatus("CREATE / LOAD PROFILE FIRST")
                return false
            end

            function Component:Remove(Value)
                if not Guard() then return false end
                local Changed = OriginalRemove(self, Value)
                Commit(self)
                return Changed
            end

            function Component:MoveUp(Value)
                if not Guard() then return end
                OriginalMoveUp(self, Value)
                Commit(self)
            end

            function Component:MoveDown(Value)
                if not Guard() then return end
                OriginalMoveDown(self, Value)
                Commit(self)
            end

            AICUI.RefreshZoneTargets()
        end

        return Feature
    end,
}
