        local Number = tonumber(Value)

        if Number and Number > 0 then
            Runtime:GetPlaceConfig().REACH_DISTANCE = Number
            AICProfile.SaveActiveProfile()
            AICUI.SetProfileStatus("REACH DISTANCE SAVED")
        end
    end,
}

